mapper.delete:
BEGIN
    /* delHardDeleteUser */
    UPDATE TB_LOGHIS
       SET USER_NUMB = NULL
     WHERE USER_NUMB = #{userNumb};

    DELETE FROM TB_REPLXX
     WHERE REPT_NUMB IN (
               SELECT REPT_NUMB
                 FROM TM_REPORT
                WHERE USER_NUMB = #{userNumb}
           );

    DELETE FROM TB_REPLXX
     WHERE (REPT_NUMB, UPER_NUMB) IN (
               SELECT REPT_NUMB
                    , REPL_NUMB
                 FROM TB_REPLXX
                WHERE USER_NUMB = #{userNumb}
           );

    DELETE FROM TB_REPLXX
     WHERE USER_NUMB = #{userNumb};

    DELETE FROM TB_LIKEXX
     WHERE USER_NUMB = #{userNumb}
        OR (
               TAGT_TYPE = 'REPORT'
           AND TAGT_NUMB IN (
                   SELECT REPT_NUMB
                     FROM TM_REPORT
                    WHERE USER_NUMB = #{userNumb}
               )
           );

    DELETE FROM TB_FOLLOW
     WHERE USER_NUMB = #{userNumb}
        OR FLOW_NUMB = #{userNumb};

    DELETE FROM TB_ALIMXX
     WHERE USER_NUMB = #{userNumb};

    DELETE FROM TB_PSHSUB
     WHERE USER_NUMB = #{userNumb};

    DELETE FROM TM_GOALXM
     WHERE USER_NUMB = #{userNumb};

    DELETE FROM TM_REPORT
     WHERE USER_NUMB = #{userNumb};

    UPDATE TM_USERXM
       SET PROF_NUMB = NULL
         , BGIM_NUMB = NULL
     WHERE USER_NUMB = #{userNumb};

    DELETE FROM TM_FILEXM
     WHERE REGI_USER = #{userNumb};

    DELETE FROM TM_USERXM
     WHERE USER_NUMB = #{userNumb};
END;
